import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing downstream (unit price in euros).
const prices = { A: 10, B: 50, C: 0.1, D: 110, E: 100.5, F: 34 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('POST /orders: 201 with id, items echoed, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const order = await res.json()
  assert.deepEqual({ items: order.items, total: order.total }, { items: [{ sku: 'A', qty: 2 }], total: 20 })
  assert.equal(typeof order.id, 'string')
})

test('POST /orders: ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across lines and asks pricing per line', async () => {
  calls.length = 0
  assert.equal(await totalOf([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]), 70)
  assert.deepEqual(calls, ['A', 'B'])
})

test('no discount at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 9 }]), 90)
})

// CHARACTERIZATION: current behaviour may be unintended — discount threshold is strictly > 100,
// so an order of exactly 100 gets no discount while 101 gets 10% off (total drops from 100 to 90).
test('discount of 10% applies just above 100 (threshold is exclusive)', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)
})

test('10% discount on larger orders', async () => {
  assert.equal(await totalOf([{ sku: 'B', qty: 4 }]), 180)
  assert.equal(await totalOf([{ sku: 'B', qty: 20 }]), 900)
})

// CHARACTERIZATION: current behaviour may be unintended — total is floored, never rounded, so
// fractional cents are dropped and the result is whole euros (e.g. 102 -> 91.8 -> 91).
test('total is truncated to whole euros after discount', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 3 }]), 91)
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100) // 100.5 -> 90.45? no: see below
})

// CHARACTERIZATION: current behaviour may be unintended — fractional unit prices are floored too.
test('fractional totals below the threshold are floored', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0) // 0.30000000000000004 -> 0
})

// CHARACTERIZATION: current behaviour may be unintended — binary floating point makes
// 110 - 110*0.1 equal 98.99999999999999, which floors to 98 instead of the expected 99.
test('floating point error can cost an extra euro on discounted orders', async () => {
  assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 98)
})

test('POST /orders: 400 when items missing, empty, not an array, or body is not JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{nope'), await post(null, '')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

// CHARACTERIZATION: current behaviour may be unintended — no validation of lines: an unknown sku
// (price undefined) or a missing qty yields NaN, serialised as total null, still 201.
test('POST /orders: unpriced sku or missing qty gives total null with 201', async () => {
  let res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
  res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

// CHARACTERIZATION: current behaviour may be unintended — unknown id answers 200, not 404.
test('GET /orders/:id for unknown id is 200 with error body', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods are 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
